recent_command_receipts.command:
cd /app && timeout 15s expect <<'EOF'
set timeout 15
spawn telnet 127.0.0.1 6665
expect {
  -re {login:|Login:} { puts "PROMPT_SEEN" }
  timeout { puts "TIMEOUT" }
  eof { puts "EOF" }
}
EOF

cd /app && if [ -f qemu.pid ]; then kill "$(cat qemu.pid)" 2>/dev/null || true; fi
nohup qemu-system-x86_64 -m 1024 -display none -monitor none -serial telnet:127.0.0.1:6665,server,nowait -cdrom alpine.iso -boot d -net none > qemu.log 2>&1 &
echo $! > qemu.pid
echo STARTED:$!
sleep 5
sed -n '1,80p' qemu.log
timeout 180s expect <<'EOF'
set timeout 20
log_user 1
spawn telnet 127.0.0.1 6665
for {set i 0} {$i < 9} {incr i} {
  send "\r"
  expect {
    -re {login:|Login:} { puts "PROMPT_SEEN"; exit 0 }
    timeout {}
    eof { puts "EOF"; exit 1 }
  }
}
puts "TIMEOUT"
exit 1
EOF

cd /app && timeout 10s expect <<'EOF'
set timeout 8
log_user 1
spawn telnet 127.0.0.1 6665
expect {
  -re {localhost login:|login:|Login:} { puts "LOGIN_PROMPT_STILL_PRESENT"; exit 0 }
  timeout { puts "TIMEOUT"; exit 1 }
  eof { puts "EOF"; exit 1 }
}
EOF

cd /app && echo '---QEMU_LOG---' && sed -n '1,120p' qemu.log && echo '---PROMPT_PROBE---' && timeout 25s expect <<'EOF'
set timeout 3
log_user 1
spawn telnet 127.0.0.1 6665
set found 0
for {set i 0} {$i < 8} {incr i} {
  expect {
    -re {localhost login:|login:|Login:} { puts "PROMPT_SEEN"; set found 1; break }
    timeout { send "\r" }
    eof { puts "EOF"; exit 1 }
  }
}
if {$found == 0} { puts "TIMEOUT"; exit 1 }
EOF

echo '---SECOND_CHECK---' && timeout 10s expect <<'EOF'
set timeout 5
log_user 1
spawn telnet 127.0.0.1 6665
expect {
  -re {Connected to 127.0.0.1.} { puts "PORT_STILL_OPEN"; exit 0 }
  timeout { puts "NO_CONNECT"; exit 1 }
  eof { puts "EOF"; exit 1 }
}
EOF
